; ============================================================================
; Doraemon 2 (J) - sound driver (Agenda) and sound data
; ROM bank 1, $4000-$7F30. Generated by tools/agenda_gen.py; reassembles
; byte-identical with RGBDS 1.0.0. See Agenda_SoundDriver.md for the format.
; ============================================================================

INCLUDE "agenda_sound.inc"

; ---- HRAM ----
DEF hSndChannel      EQU $FF90 ; hardware channel being processed (0-3)
DEF hSndStructOfs    EQU $FF91 ; struct offset ($00/$30/$60/$90, $C0 = SFX)
DEF hSndTempo        EQU $FF92 ; frames per tick - 1
DEF hSndTempoCount   EQU $FF93 ; frame counter for the tempo
DEF hSndFlags        EQU $FF94 ; bits 0-3 channel on, bit 4 SFX, bit 7 no-loop
DEF hSndMarker       EQU $FF95 ; last $B4 argument (read by the game)
DEF hSndSlur         EQU $FF96 ; 1 = $A4 seen in this row
DEF hSndMasterVol    EQU $FF97 ; NR50 copy ($B6)
DEF hSndSfxChannel   EQU $FF98 ; channel of the playing SFX
DEF hSndMuted        EQU $FF99 ; 1 = channel in use by the SFX: no register writes
DEF hSndRetrigger    EQU $FF9A ; 1 = write NRx4 with trigger at the end of the tick
DEF hSndSfxId        EQU $FF9B ; last SFX id
DEF hSndSfxPriority  EQU $FF9C ; priority of the playing SFX
DEF hSndMusicId      EQU $FF9D ; last music id
DEF hSndUnused       EQU $FF9E ; not used by the driver
DEF hSndSfxFrame     EQU $FF9F ; SFX frame divider

; ---- WRAM ----
DEF wSndTracks      EQU $C100 ; 5 track structs of TRK_SIZEOF: ch1-ch4, SFX
DEF wSndSave        EQU $C200 ; copy of wSndTracks (Sound_SaveMusic)
DEF wSndSaveHram    EQU $C2F0 ; copy of the 16 HRAM bytes

SECTION "Sound driver", ROMX[$4000], BANK[1]

; Jump table, called from bank 0.
Sound_JumpTable::
    jp Sound_Init                   ; $4000
    jp Sound_Update                 ; $4003
    jp Sound_PlayMusic              ; $4006
    jp Sound_PlaySfx                ; $4009
    jp Sound_StopMusic              ; $400C
    jp Sound_SaveMusic              ; $400F
    jp Sound_RestoreMusic           ; $4012

    ds $0B, $FF                     ; unused

; Id remap tables. Not used by the driver: bank-0 code reads them when
; [$D128] != 0 (music) or [$FFBA] = 1 (SFX) and plays the id found here.
MusicRemap:
    db $00, $01, $02, $03, $04, $05, $06, $07 ; music $00-$07
    db $08, $0D, $0B, $0B, $0C, $0D, $0F, $0F ; music $08-$0F
    db $11, $11, $12, $13, $14, $15, $16, $17 ; music $10-$17
    db $18, $19, $1A, $1B, $1C, $1D, $1F, $1F ; music $18-$1F
SfxRemap:
    db $20, $21, $22, $23, $24, $3F, $3F, $3F ; SFX $00-$07
    db $28, $29, $3F, $3F, $2C, $2D, $2E, $3F ; SFX $08-$0F
    db $30, $3F, $3F, $33, $33, $35, $36, $37 ; SFX $10-$17
    db $38, $39, $3A, $3B, $3F, $3E, $3F ; SFX $18-$1E

; Sound_SaveMusic: back up all track structs and the HRAM variables, then
; start the silent song (all channels free). Used around jingles.
Sound_SaveMusic::
    ldh a,[rIE]                     ; $405F IE: mask the LCD STAT interrupt (bit 1)
    push af                         ; $4061
    res 1,a                         ; $4062
    ldh [rIE],a                     ; $4064
    ld hl,wSndTracks                ; $4066
    ld de,wSndSave                  ; $4069
    ld bc,$0100                     ; $406C
    call Snd_CopyBytes              ; $406F
    ld hl,hSndChannel               ; $4072
    ld de,wSndSaveHram              ; $4075
    ld bc,$0010                     ; $4078
    call Snd_CopyBytes              ; $407B
    ldh a,[hSndFlags]               ; $407E
    and $F0                         ; $4080
    ldh [hSndFlags],a               ; $4082
    pop af                          ; $4084
    ldh [rIE],a                     ; $4085 restore IE
    call Sound_StopMusic            ; $4087
    ret                             ; $408A

; Sound_RestoreMusic: undo Sound_SaveMusic. The wave RAM and the hardware
; registers are not restored; each channel sounds again at its next note.
Sound_RestoreMusic::
    ldh a,[rIE]                     ; $408B IE: mask the LCD STAT interrupt (bit 1)
    push af                         ; $408D
    res 1,a                         ; $408E
    ldh [rIE],a                     ; $4090
    ld hl,wSndSave                  ; $4092
    ld de,wSndTracks                ; $4095
    ld bc,$0100                     ; $4098
    call Snd_CopyBytes              ; $409B
    ld hl,wSndSaveHram              ; $409E
    ld de,hSndChannel               ; $40A1
    ld bc,$0010                     ; $40A4
    call Snd_CopyBytes              ; $40A7
    pop af                          ; $40AA
    ldh [rIE],a                     ; $40AB restore IE
    ret                             ; $40AD
Snd_CopyBytes:
    ld a,[hl+]                      ; $40AE
    ld [de],a                       ; $40AF
    inc de                          ; $40B0
    dec bc                          ; $40B1
    ld a,b                          ; $40B2
    or c                            ; $40B3
    jr nz,Snd_CopyBytes             ; $40B4
    ret                             ; $40B6

; Sound_PlaySfx: a = SFX id. Header = [channel 0-3, priority], then track data.
; Ignored if priority < the priority of the SFX already playing.
Sound_PlaySfx::
    ldh [hSndSfxId],a               ; $40B7
    ld l,a                          ; $40B9
    ld h,$00                        ; $40BA
    add hl,hl                       ; $40BC
    ld de,SfxTable                  ; $40BD
    add hl,de                       ; $40C0
    jp Snd_StartSfx                 ; $40C1

; Sound_PlayMusic: a = song id. MusicTable has 4 track pointers per song.
Sound_PlayMusic::
    ldh [hSndMusicId],a             ; $40C4
    ld l,a                          ; $40C6
    ld h,$00                        ; $40C7
    add hl,hl                       ; $40C9
    add hl,hl                       ; $40CA
    add hl,hl                       ; $40CB
    ld de,MusicTable                ; $40CC
    add hl,de                       ; $40CF
    jp Snd_StartMusic               ; $40D0

; Register values written by Sound_Init to NR10-NR23 ($FF10-$FF23)
InitRegs:
    db $08, $00, $02, $00, $80
    db $00, $00, $02, $00, $80
    db $00, $00, $00, $00, $80
    db $00, $00, $02, $00, $80

; Sound_StopMusic: the silent song (4 x the same track)
SilentSong:
    dw SilentTrack, SilentTrack, SilentTrack, SilentTrack
SilentTrack:
    db $B6, $77                     ; master volume (NR50 $77)
    db $A6, $00                     ; volume 0
    db $00                          ; rest
    db $A0                          ; end (loop to start; stop if $A2)

; $A6 on ch3: volume 0-15 -> NR32 output level
WaveVolTable:
    db $00, $00, $60, $60, $60, $60, $40, $40, $40, $40, $20, $20, $20, $20, $20, $20

; Length codes $80-$8D (ticks)
LengthTable:
    db 64                           ; $80
    db 48                           ; $81
    db 32                           ; $82
    db 24                           ; $83
    db 16                           ; $84
    db 12                           ; $85
    db 8                            ; $86
    db 6                            ; $87
    db 4                            ; $88
    db 3                            ; $89
    db 2                            ; $8A
    db 1                            ; $8B
    db 1                            ; $8C
    db 1                            ; $8D

; Periods for notes $24 (C2) and up
FreqTable:
    dw $002C                        ; note $24 C2
    dw $009D                        ; note $25 C#2
    dw $0107                        ; note $26 D2
    dw $016B                        ; note $27 D#2
    dw $01C9                        ; note $28 E2
    dw $0223                        ; note $29 F2
    dw $0277                        ; note $2A F#2
    dw $02C7                        ; note $2B G2
    dw $0312                        ; note $2C G#2
    dw $0358                        ; note $2D A2
    dw $039B                        ; note $2E A#2
    dw $03DA                        ; note $2F B2
    dw $0416                        ; note $30 C3
    dw $044E                        ; note $31 C#3
    dw $0483                        ; note $32 D3
    dw $04B5                        ; note $33 D#3
    dw $04E5                        ; note $34 E3
    dw $0511                        ; note $35 F3
    dw $053B                        ; note $36 F#3
    dw $0563                        ; note $37 G3
    dw $0589                        ; note $38 G#3
    dw $05AC                        ; note $39 A3
    dw $05CD                        ; note $3A A#3
    dw $05ED                        ; note $3B B3
    dw $060C                        ; note $3C C4
    dw $0627                        ; note $3D C#4
    dw $0642                        ; note $3E D4
    dw $065B                        ; note $3F D#4
    dw $0672                        ; note $40 E4
    dw $0689                        ; note $41 F4
    dw $069E                        ; note $42 F#4
    dw $06B2                        ; note $43 G4
    dw $06C4                        ; note $44 G#4
    dw $06D6                        ; note $45 A4
    dw $06E7                        ; note $46 A#4
    dw $06F7                        ; note $47 B4
    dw $0706                        ; note $48 C5
    dw $0714                        ; note $49 C#5
    dw $0721                        ; note $4A D5
    dw $072D                        ; note $4B D#5
    dw $0739                        ; note $4C E5
    dw $0744                        ; note $4D F5
    dw $074F                        ; note $4E F#5
    dw $0759                        ; note $4F G5
    dw $0762                        ; note $50 G#5
    dw $076B                        ; note $51 A5
    dw $0773                        ; note $52 A#5
    dw $077B                        ; note $53 B5
    dw $0783                        ; note $54 C6
    dw $078A                        ; note $55 C#6
    dw $0790                        ; note $56 D6
    dw $0797                        ; note $57 D#6
    dw $079D                        ; note $58 E6
    dw $07A2                        ; note $59 F6
    dw $07A7                        ; note $5A F#6
    dw $07AC                        ; note $5B G6
    dw $07B1                        ; note $5C G#6
    dw $07B6                        ; note $5D A6
    dw $07BA                        ; note $5E A#6
    dw $07BE                        ; note $5F B6
    dw $07C1                        ; note $60 C7
    dw $07C5                        ; note $61 C#7
    dw $07C8                        ; note $62 D7
    dw $07CB                        ; note $63 D#7
    dw $07CE                        ; note $64 E7
    dw $07D1                        ; note $65 F7
    dw $07D4                        ; note $66 F#7
    dw $07D6                        ; note $67 G7
    dw $07D9                        ; note $68 G#7
    dw $07DB                        ; note $69 A7
    dw $07DD                        ; note $6A A#7
    dw $07DF                        ; note $6B B7
    dw $07E1                        ; note $6C C8
    dw $07E2                        ; note $6D C#8
    dw $07E4                        ; note $6E D8
    dw $07E6                        ; note $6F D#8
    dw $07E7                        ; note $70 E8
    dw $07E9                        ; note $71 F8
    dw $07EA                        ; note $72 F#8
    dw $07EB                        ; note $73 G8
    dw $07EC                        ; note $74 G#8
    dw $07ED                        ; note $75 A8
    dw $07EE                        ; note $76 A#8
    dw $07EF                        ; note $77 B8
    dw $07F0                        ; note $78 C9
    dw $07F1                        ; note $79 C#9
    dw $07F2                        ; note $7A D9
    dw $07F3                        ; note $7B D#9
    dw $07F4                        ; note $7C E9

; Commands $A0-$B7
CommandTable:
    dw Cmd_End                      ; $A0
    dw Cmd_LoopOn                   ; $A1
    dw Cmd_LoopOff                  ; $A2
    dw Cmd_LoopStart                ; $A3
    dw Cmd_Slur                     ; $A4
    dw Cmd_DefaultLength            ; $A5
    dw Cmd_Volume                   ; $A6
    dw Cmd_Pan                      ; $A7
    dw Cmd_Envelope                 ; $A8
    dw Cmd_LoopEnd                  ; $A9
    dw Cmd_Duty                     ; $AA
    dw Cmd_SeqTable                 ; $AB
    dw Cmd_Call                     ; $AC
    dw Cmd_SeqTable                 ; $AD
    dw Cmd_Wave                     ; $AE
    dw Cmd_Tempo                    ; $AF
    dw Cmd_Detune                   ; $B0
    dw Cmd_Transpose                ; $B1
    dw Cmd_Gate                     ; $B2
    dw Cmd_Jump                     ; $B3
    dw Cmd_Marker                   ; $B4
    dw Cmd_Return                   ; $B5
    dw Cmd_MasterVolume             ; $B6
    dw Cmd_Vibrato                  ; $B7

; Sound_Update: call once per frame.
; Music tracks tick once every (tempo+1) frames; the SFX track every 2nd frame.
Sound_Update::
    ld de,hSndTempoCount            ; $41F5 tempo divider
    ld a,[de]                       ; $41F8
    ld hl,hSndTempo                 ; $41F9
    cp [hl]                         ; $41FC
    jr z,.tick                      ; $41FD
    inc a                           ; $41FF
    ld [de],a                       ; $4200
    jr .sfx                         ; $4201
.tick
    xor a                           ; $4203 tick: reset divider
    ld [de],a                       ; $4204
    ldh [hSndChannel],a             ; $4205
    ldh [hSndStructOfs],a           ; $4207
    ldh a,[hSndFlags]               ; $4209 b = channel-on bits
    ld b,a                          ; $420B
.channelLoop
    rr b                            ; $420C next channel bit
    jr nc,.nextChannel              ; $420E
    push bc                         ; $4210
    ld l,TRK_FLAGS                  ; $4211
    call Snd_GetVar                 ; $4213
    and $01                         ; $4216 muted = SFX owns this channel
    ldh [hSndMuted],a               ; $4218
    call Snd_TickTrack              ; $421A
    pop bc                          ; $421D
.nextChannel
    ldh a,[hSndStructOfs]           ; $421E
    add a,$30                       ; $4220 next struct
    ldh [hSndStructOfs],a           ; $4222
    ldh a,[hSndChannel]             ; $4224
    inc a                           ; $4226
    ldh [hSndChannel],a             ; $4227
    cp $04                          ; $4229
    jr c,.channelLoop               ; $422B
.sfx
    ldh a,[hSndFlags]               ; $422D
    bit 4,a                         ; $422F SFX playing?
    ret z                           ; $4231
    ld hl,hSndSfxFrame              ; $4232 SFX runs every 2nd frame
    inc [hl]                        ; $4235
    ld a,[hl]                       ; $4236
    rra                             ; $4237
    ret c                           ; $4238
    ldh a,[hSndSfxChannel]          ; $4239 SFX: channel = its target channel
    ldh [hSndChannel],a             ; $423B
    xor a                           ; $423D
    ldh [hSndMuted],a               ; $423E
    ld a,$C0                        ; $4240 struct 4
    ldh [hSndStructOfs],a           ; $4242

; Snd_TickTrack: one tick of the track at hSndStructOfs on hardware
; channel hSndChannel. hSndMuted = channel in use by the SFX (no register writes).
Snd_TickTrack:
    xor a                           ; $4244
    ldh [hSndRetrigger],a           ; $4245
    ld l,TRK_LENGTH                 ; $4247
    call Snd_GetVar                 ; $4249
    dec [hl]                        ; $424C length done -> new row
    jr z,.newRow                    ; $424D
    ld l,TRK_GATECOUNT              ; $424F gate counter
    call Snd_GetVarH                ; $4251
    or a                            ; $4254
    ret z                           ; $4255 already released: nothing to do
    dec [hl]                        ; $4256
    jp z,Snd_NoteOff                ; $4257 gate reached -> note off
    ld l,TRK_FLAGS                  ; $425A
    call Snd_GetVar                 ; $425C
    bit 7,[hl]                      ; $425F SFX just ended here: wait for a new row
    ret nz                          ; $4261
    ldh a,[hSndChannel]             ; $4262
    cp $02                          ; $4264
    call nz,Snd_EnvTick             ; $4266 envelope (not ch3)
    ldh a,[hSndChannel]             ; $4269
    cp $03                          ; $426B
    call z,Snd_SeqTick              ; $426D noise list (ch4)
    ldh a,[hSndChannel]             ; $4270
    cp $02                          ; $4272
    call c,Snd_VibratoTick          ; $4274 vibrato (ch1/ch2)
    jr .output                      ; $4277
.newRow
    ld l,TRK_FLAGS                  ; $4279
    call Snd_GetVarH                ; $427B
    res 7,[hl]                      ; $427E
    xor a                           ; $4280 clear the slur flag for this row
    ldh [hSndSlur],a                ; $4281
    ld l,TRK_PTR                    ; $4283
    call Snd_GetVarWord             ; $4285
    ld e,c                          ; $4288
    ld d,b                          ; $4289
.readByte
    ld a,[de]                       ; $428A
    inc de                          ; $428B
    cp $80                          ; $428C $80-$FF: command
    jr nc,.command                  ; $428E
    push af                         ; $4290
    ld b,a                          ; $4291
    ld l,TRK_NOTE                   ; $4292 a = old note
    call Snd_GetVar                 ; $4294
    ld [hl],b                       ; $4297 TRK_NOTE = new note
    ld l,TRK_PREVNOTE               ; $4298
    call Snd_SetVar                 ; $429A TRK_PREVNOTE = old note
    pop af                          ; $429D
    call Snd_PlayNote               ; $429E
    jr .saveRow                     ; $42A1
.command
    call Snd_DoCommand              ; $42A3
    ldh a,[hSndStructOfs]           ; $42A6
    cp $C0                          ; $42A8 SFX struct?
    jr nz,.music                    ; $42AA
    ldh a,[hSndFlags]               ; $42AC
    bit 4,a                         ; $42AE SFX still running: keep parsing
    jr z,.saveRow                   ; $42B0
    jr .readByte                    ; $42B2
.music
    call Snd_IsChannelOn            ; $42B4 music: keep parsing while the channel is on
    jr nz,.readByte                 ; $42B7
.saveRow
    ld c,e                          ; $42B9
    ld b,d                          ; $42BA
    ld l,TRK_PTR                    ; $42BB
    call Snd_SetVarWord             ; $42BD
.output
    ldh a,[hSndRetrigger]           ; $42C0 retrigger requested?
    or a                            ; $42C2
    ret z                           ; $42C3
    ldh a,[hSndMuted]               ; $42C4
    or a                            ; $42C6 not while the SFX owns the channel
    ret nz                          ; $42C7
    ld h,a                          ; $42C8
    ldh a,[hSndChannel]             ; $42C9
    cp $03                          ; $42CB
    jr z,.trigger                   ; $42CD
    cp $02                          ; $42CF
    jr nz,.notWave                  ; $42D1
    ld l,TRK_VOLUME                 ; $42D3
    call Snd_GetVar                 ; $42D5
    ldh [rNR32],a                   ; $42D8 NR32 = output level
    ld a,$80                        ; $42DA
    ldh [rNR30],a                   ; $42DC wave DAC on
.notWave
    ld l,TRK_FREQ+1                 ; $42DE
    call Snd_GetVar                 ; $42E0 period high bits
    ld h,a                          ; $42E3
.trigger
    call Snd_GetChannelRegs         ; $42E4
    ld c,e                          ; $42E7
    inc c                           ; $42E8
    ld a,$80                        ; $42E9
    or h                            ; $42EB
    ldh [c],a                       ; $42EC NRx4 = trigger | period high
    ret                             ; $42ED

; Snd_NoteOff: silence the channel (NRx2 = 8, retrigger; ch3: NR30 = 0).
Snd_NoteOff:
    ldh a,[hSndMuted]               ; $42EE
    or a                            ; $42F0
    ret nz                          ; $42F1
    ldh a,[hSndChannel]             ; $42F2
    cp $02                          ; $42F4
    jr nz,Snd_WaveOff.notWave       ; $42F6
Snd_WaveOff:
    xor a                           ; $42F8
    ldh [rNR32],a                   ; $42F9 ch3: NR32 = 0, NR30 = 0
    ldh [rNR30],a                   ; $42FB
    ret                             ; $42FD
.notWave
    push de                         ; $42FE
    call Snd_GetChannelRegs         ; $42FF
    ld c,e                          ; $4302
    dec c                           ; $4303
    ld a,$08                        ; $4304
    ldh [c],a                       ; $4306 NRx2 = 8 (volume 0, up)
    inc c                           ; $4307
    inc c                           ; $4308
    ld a,$80                        ; $4309
    ldh [c],a                       ; $430B NRx4 = trigger
    pop de                          ; $430C
    ret                             ; $430D

; Snd_KeyOn: request the trigger write and write the period (or start the drum).
Snd_KeyOn:
    ldh a,[hSndMuted]               ; $430E
    or a                            ; $4310
    ret nz                          ; $4311
    inc a                           ; $4312
    ldh [hSndRetrigger],a           ; $4313 request the trigger write
Snd_WriteFreq:
    push de                         ; $4315
    call Snd_GetChannelRegs         ; $4316
    ldh a,[rNR52]                   ; $4319
    or d                            ; $431B
    ldh [rNR52],a                   ; $431C NR52 |= channel bit (read-only bits, no effect)
    ldh a,[hSndChannel]             ; $431E
    cp $03                          ; $4320
    jr nz,.notNoise                 ; $4322
    call Snd_DrumInit               ; $4324 ch4: start the drum
    jr .done                        ; $4327
.notNoise
    ld l,TRK_FREQ                   ; $4329
    call Snd_GetVarWord             ; $432B
    ld a,c                          ; $432E
    ld c,e                          ; $432F
    ldh [c],a                       ; $4330 NRx3
    inc c                           ; $4331
    ld a,b                          ; $4332
    ldh [c],a                       ; $4333 NRx4 (no trigger yet)
.done
    pop de                          ; $4334
    ret                             ; $4335

; Snd_GetChannelRegs: d = NR52-style channel bit | $80, e = LOW(NRx3).
Snd_GetChannelRegs:
    ldh a,[hSndChannel]             ; $4336
    ld d,$81                        ; $4338
    ld e,$13                        ; $433A
    or a                            ; $433C
    ret z                           ; $433D
    ld d,$82                        ; $433E
    ld e,$18                        ; $4340
    dec a                           ; $4342
    ret z                           ; $4343
    ld d,$84                        ; $4344
    ld e,$1D                        ; $4346
    dec a                           ; $4348
    ret z                           ; $4349
    ld d,$88                        ; $434A
    ld e,$22                        ; $434C
    ret                             ; $434E

; Snd_PlayNote: a = note byte (rest, or note). Handles the slur, key-on and
; the optional length byte that follows the note.
Snd_PlayNote:
    cp $00                          ; $434F rest?
    jr nz,.note                     ; $4351
    ld l,TRK_FLAGS                  ; $4353
    call Snd_GetVar                 ; $4355
    res 1,[hl]                      ; $4358 rest clears the slur
    call Snd_NoteOff                ; $435A
    jr .length                      ; $435D
.note
    call Snd_CalcFreq               ; $435F
    ld l,TRK_FLAGS                  ; $4362
    call Snd_GetVar                 ; $4364
    ldh a,[hSndSlur]                ; $4367 slur ($A4) on this row?
    or a                            ; $4369
    jr z,.noSlur                    ; $436A
    bit 1,[hl]                      ; $436C
    jr nz,.compare                  ; $436E
    set 1,[hl]                      ; $4370 first slurred note: key on, remember
    jr .keyOn                       ; $4372
.noSlur
    bit 1,[hl]                      ; $4374
    jr z,.keyOn                     ; $4376
    res 1,[hl]                      ; $4378 last note of a slur
.compare
    ld l,TRK_NOTE                   ; $437A
    call Snd_GetVarH                ; $437C
    ld b,a                          ; $437F
    ld l,TRK_PREVNOTE               ; $4380
    call Snd_GetVarH                ; $4382
    cp b                            ; $4385 same pitch as the previous note: tie, no key-on
    jr z,.length                    ; $4386
.keyOn
    call Snd_NoteOff                ; $4388 release, then key on
    call Snd_KeyOn                  ; $438B
    push de                         ; $438E
    ldh a,[hSndChannel]             ; $438F
    cp $00                          ; $4391
    call z,Snd_SweepInit            ; $4393 ch1: sweep
    ldh a,[hSndChannel]             ; $4396
    cp $02                          ; $4398
    call nz,Snd_VolumeInit          ; $439A not ch3: volume/duty/envelope
    ldh a,[hSndChannel]             ; $439D
    cp $02                          ; $439F
    call c,Snd_VibratoInit          ; $43A1 ch1/ch2: vibrato
    pop de                          ; $43A4
.length
    ld a,[de]                       ; $43A5
    cp $80                          ; $43A6 length byte follows?
    jr c,.defaultLength             ; $43A8
    cp $A0                          ; $43AA
    jr nc,.defaultLength            ; $43AC
    call Snd_GetLength              ; $43AE ticks from LengthTable
    inc de                          ; $43B1
    jr .setLength                   ; $43B2
.defaultLength
    ld l,TRK_DEFLEN                 ; $43B4
    call Snd_GetVar                 ; $43B6 no: default length
.setLength
    ld b,a                          ; $43B9
    ld l,TRK_LENGTH                 ; $43BA
    call Snd_SetVar                 ; $43BC TRK_LENGTH
    ld l,TRK_GATE                   ; $43BF
    call Snd_GetVarH                ; $43C1
    or a                            ; $43C4 gate 0 = full length
    jr z,.setGate                   ; $43C5
    ld c,a                          ; $43C7
    srl b                           ; $43C8 b = length / 8 (at least 1)
    srl b                           ; $43CA
    srl b                           ; $43CC
    jr nz,.multiply                 ; $43CE
    ld b,$01                        ; $43D0
.multiply
    xor a                           ; $43D2
.mulLoop
    add a,b                         ; $43D3 b * gate
    dec c                           ; $43D4
    jr nz,.mulLoop                  ; $43D5
    ld b,a                          ; $43D7
.setGate
    ld a,b                          ; $43D8
    ld l,TRK_GATECOUNT              ; $43D9
    jp Snd_SetVar                   ; $43DB TRK_GATECOUNT

; Snd_CalcFreq: TRK_FREQ = FreqTable[note - $24 + transpose] + detune.
; Notes below $24 give period 0 (used for noise "notes").
Snd_CalcFreq:
    ld l,TRK_NOTE                   ; $43DE
    call Snd_GetVar                 ; $43E0
    ld bc,$0000                     ; $43E3
    cp $24                          ; $43E6 below $24: period 0
    jr c,.store                     ; $43E8
    sub $24                         ; $43EA
    inc hl                          ; $43EC
    add a,[hl]                      ; $43ED + transpose
    push hl                         ; $43EE
    ld l,a                          ; $43EF
    ld h,b                          ; $43F0
    add hl,hl                       ; $43F1
    ld bc,FreqTable                 ; $43F2 FreqTable
    add hl,bc                       ; $43F5
    ld a,[hl+]                      ; $43F6
    ld h,[hl]                       ; $43F7
    ld l,a                          ; $43F8
    pop bc                          ; $43F9
    inc bc                          ; $43FA
    ld a,[bc]                       ; $43FB + detune (signed)
    ld c,a                          ; $43FC
    ld b,$00                        ; $43FD
    bit 7,a                         ; $43FF
    jr z,.positive                  ; $4401
    dec b                           ; $4403
.positive
    add hl,bc                       ; $4404
    ld c,l                          ; $4405
    ld b,h                          ; $4406
.store
    ld l,TRK_FREQ                   ; $4407
    jp Snd_SetVarWord               ; $4409

; Snd_VibratoTick: ch1/ch2 only. Modes: 1 triangle (one-sided), 2 slide down,
; 3 slide up. Changes TRK_DETUNE and rewrites the period without retrigger.
Snd_VibratoTick:
    ld l,TRK_VIBMODE                ; $440C
    call Snd_GetVar                 ; $440E
    ld b,a                          ; $4411 vibrato off
    or a                            ; $4412
    ret z                           ; $4413
    ld l,TRK_VIBDELAY               ; $4414
    call Snd_GetVar                 ; $4416
    or a                            ; $4419
    jr z,.step                      ; $441A still in the delay
    dec [hl]                        ; $441C
    ret                             ; $441D
.step
    ld l,TRK_VIBRATE                ; $441E
    call Snd_GetVar                 ; $4420
    dec [hl]                        ; $4423 rate countdown
    ret nz                          ; $4424
    ld l,TRK_VIBRATER               ; $4425
    call Snd_GetVar                 ; $4427
    ld l,TRK_VIBRATE                ; $442A
    call Snd_SetVar                 ; $442C
    ld l,TRK_VIBSTEP                ; $442F c = step
    call Snd_GetVar                 ; $4431
    ld c,a                          ; $4434
    ld l,TRK_DETUNE                 ; $4435
    call Snd_GetVar                 ; $4437
    dec b                           ; $443A mode 1
    jr z,.triangle                  ; $443B
    dec b                           ; $443D mode 2
    jr z,.slideDown                 ; $443E
    add a,c                         ; $4440 mode 3: up
    ld [hl],a                       ; $4441
    jr .update                      ; $4442
.slideDown
    sub c                           ; $4444 mode 2: down
    ld [hl],a                       ; $4445
    jr .update                      ; $4446
.triangle
    ld l,TRK_VIBHALF                ; $4448
    call Snd_GetVar                 ; $444A
    dec [hl]                        ; $444D half period done:
    jr nz,.apply                    ; $444E
    ld l,TRK_VIBHALFR               ; $4450
    call Snd_GetVar                 ; $4452
    ld l,TRK_VIBHALF                ; $4455
    call Snd_SetVar                 ; $4457
    ld a,c                          ; $445A
    cpl                             ; $445B negate the step
    inc a                           ; $445C
    ld c,a                          ; $445D
    ld l,TRK_VIBSTEP                ; $445E
    call Snd_SetVar                 ; $4460
.apply
    ld l,TRK_DETUNE                 ; $4463
    call Snd_GetVar                 ; $4465
    add a,c                         ; $4468
    ld [hl],a                       ; $4469
.update
    ldh a,[hSndMuted]               ; $446A
    or a                            ; $446C
    ret nz                          ; $446D not while muted
    call Snd_CalcFreq               ; $446E
    ldh a,[hSndChannel]             ; $4471
    cp $02                          ; $4473
    jp z,Snd_KeyOn                  ; $4475 (only ch1/ch2 get here, so always the second jump)
    jp Snd_WriteFreq                ; $4478

; Snd_VibratoInit: reload all vibrato counters at key-on; detune = 0.
Snd_VibratoInit:
    ld l,TRK_VIBMODE                ; $447B
    call Snd_GetVar                 ; $447D
    or a                            ; $4480
    ret z                           ; $4481
    ld l,TRK_VIBDEPTH               ; $4482
    call Snd_GetVar                 ; $4484 step = depth
    ld l,TRK_VIBSTEP                ; $4487
    call Snd_SetVar                 ; $4489
    ld l,TRK_VIBDELAYR              ; $448C
    call Snd_GetVar                 ; $448E delay
    ld l,TRK_VIBDELAY               ; $4491
    call Snd_SetVar                 ; $4493
    ld l,TRK_VIBRATER               ; $4496
    call Snd_GetVar                 ; $4498 rate
    ld l,TRK_VIBRATE                ; $449B
    call Snd_SetVar                 ; $449D
    ld l,TRK_VIBHALFR               ; $44A0
    call Snd_GetVar                 ; $44A2 half period
    ld l,TRK_VIBHALF                ; $44A5
    call Snd_SetVar                 ; $44A7
    xor a                           ; $44AA
    ld l,TRK_DETUNE                 ; $44AB
    jp Snd_SetVar                   ; $44AD detune = 0

; Snd_VolumeInit: key-on for ch1/2/4: NRx2 volume nibble, NRx1 duty, and
; start the $A8 envelope list if one is set.
Snd_VolumeInit:
    ldh a,[hSndMuted]               ; $44B0
    or a                            ; $44B2
    ret nz                          ; $44B3
    call Snd_GetChannelRegs         ; $44B4
    ld l,TRK_VOLUME                 ; $44B7
    call Snd_GetVar                 ; $44B9
    swap a                          ; $44BC volume nibble -> NRx2 bits 4-7
    ld b,a                          ; $44BE
    ld c,e                          ; $44BF
    dec c                           ; $44C0
    ldh a,[c]                       ; $44C1
    and $0F                         ; $44C2
    or b                            ; $44C4
    ldh [c],a                       ; $44C5
    ld a,[hl+]                      ; $44C6
    ld a,[hl]                       ; $44C7
    ld c,e                          ; $44C8
    dec c                           ; $44C9
    dec c                           ; $44CA
    ldh [c],a                       ; $44CB NRx1 = duty
    ld l,TRK_FLAGS                  ; $44CC
    call Snd_GetVarH                ; $44CE
    bit 2,a                         ; $44D1 envelope list set?
    ret z                           ; $44D3
    set 5,[hl]                      ; $44D4 start it
Snd_EnvStart:
    ld l,TRK_ENVBASE                ; $44D6
    call Snd_GetVarWord             ; $44D8
    ld l,TRK_ENVPTR                 ; $44DB
    call Snd_SetVarWord             ; $44DD TRK_ENVPTR = TRK_ENVBASE

; Snd_EnvNextStep: read the next (NRx2 value, ticks) pair of the envelope list.
Snd_EnvNextStep:
    ld l,TRK_ENVPTR                 ; $44E0
    call Snd_GetVarWord             ; $44E2
    ld a,[bc]                       ; $44E5
    ld e,a                          ; $44E6
    inc bc                          ; $44E7
    ld a,[bc]                       ; $44E8
    ld d,a                          ; $44E9
    inc bc                          ; $44EA
    ld a,b                          ; $44EB
    ld [hl-],a                      ; $44EC
    ld [hl],c                       ; $44ED
    ld a,e                          ; $44EE
    ld l,TRK_ENVVALUE               ; $44EF value
    call Snd_SetVar                 ; $44F1
    ld a,d                          ; $44F4
    ld l,TRK_ENVCOUNT               ; $44F5 ticks
    call Snd_SetVar                 ; $44F7
    cp $FE                          ; $44FA $FE/$FF: no write
    ret nc                          ; $44FC
    ldh a,[hSndMuted]               ; $44FD
    or a                            ; $44FF
    ret nz                          ; $4500
    ld c,$12                        ; $4501
    ldh a,[hSndChannel]             ; $4503
    cp $00                          ; $4505
    jr z,.write                     ; $4507
    ld c,$17                        ; $4509
    cp $01                          ; $450B
    jr z,.write                     ; $450D
    ld c,$21                        ; $450F
.write
    ld a,e                          ; $4511 NRx2 = value
    ldh [c],a                       ; $4512
    ret                             ; $4513

; Snd_EnvTick: count down the current envelope step; at 0 take the next pair
; and retrigger. Duration $FE = restart the list, $FF = stop.
Snd_EnvTick:
    ld l,TRK_FLAGS                  ; $4514
    call Snd_GetVar                 ; $4516
    bit 5,a                         ; $4519
    ret z                           ; $451B
    ld l,TRK_ENVCOUNT               ; $451C
    call Snd_GetVar                 ; $451E
    dec [hl]                        ; $4521
    ret nz                          ; $4522
    call Snd_EnvNextStep            ; $4523
    ld a,d                          ; $4526
    cp $FE                          ; $4527 $FE: restart
    jp z,Snd_EnvStart               ; $4529
    cp $FF                          ; $452C $FF: stop
    jr nz,.retrigger                ; $452E
    ld l,TRK_FLAGS                  ; $4530
    call Snd_GetVar                 ; $4532
    res 5,[hl]                      ; $4535
    ret                             ; $4537
.retrigger
    ldh a,[hSndMuted]               ; $4538
    or a                            ; $453A
    ret nz                          ; $453B
    inc a                           ; $453C
    ldh [hSndRetrigger],a           ; $453D retrigger to apply the new NRx2
    ret                             ; $453F

; Snd_SweepInit (ch1): NR10 = first value of the $AB/$AD list.
Snd_SweepInit:
    ld l,TRK_SEQTABLE               ; $4540
    call Snd_GetVarWord             ; $4542
    jr Snd_DrumInit.startSeq        ; $4545

; Snd_DrumInit (ch4): kit entry (note - $0A) & 7 = [noise list, envelope list].
Snd_DrumInit:
    ld l,TRK_SEQTABLE               ; $4547
    call Snd_GetVarWord             ; $4549
    ld l,TRK_NOTE                   ; $454C
    call Snd_GetVar                 ; $454E
    sub $0A                         ; $4551 drum = (note - $0A) & 7
    and $07                         ; $4553
    add a,a                         ; $4555
    add a,a                         ; $4556
    ld l,a                          ; $4557
    ld h,$00                        ; $4558
    add hl,bc                       ; $455A
    ld a,[hl+]                      ; $455B
    ld c,a                          ; $455C
    ld a,[hl+]                      ; $455D
    ld b,a                          ; $455E
    push bc                         ; $455F
    ld a,[hl+]                      ; $4560
    ld c,a                          ; $4561
    ld b,[hl]                       ; $4562
    call Snd_SetEnvelope            ; $4563 second word: envelope list
    pop bc                          ; $4566
.startSeq
    ld l,TRK_SEQPTR                 ; $4567
    call Snd_SetVarWord             ; $4569 first word: noise list
    ld l,TRK_FLAGS                  ; $456C
    call Snd_GetVar                 ; $456E
    bit 3,a                         ; $4571 table set?
    ret z                           ; $4573
    set 4,[hl]                      ; $4574

; Snd_SeqNextStep: read the next (value, ticks) pair; NR10 (ch1) or NR43 (ch4).
Snd_SeqNextStep:
    ld l,TRK_SEQPTR                 ; $4576
    call Snd_GetVarWord             ; $4578
    ld a,[bc]                       ; $457B
    ld e,a                          ; $457C
    inc bc                          ; $457D
    ld a,[bc]                       ; $457E
    ld d,a                          ; $457F
    inc bc                          ; $4580
    ld a,b                          ; $4581
    ld [hl-],a                      ; $4582
    ld [hl],c                       ; $4583
    ld a,e                          ; $4584
    ld l,TRK_SEQVALUE               ; $4585
    call Snd_SetVar                 ; $4587 value
    ld a,d                          ; $458A
    ld l,TRK_SEQCOUNT               ; $458B
    call Snd_SetVar                 ; $458D ticks
    ld a,d                          ; $4590
    cp $FE                          ; $4591 $FE/$FF: no write
    ret nc                          ; $4593
    ldh a,[hSndMuted]               ; $4594
    or a                            ; $4596
    ret nz                          ; $4597
    ld c,$22                        ; $4598
    ldh a,[hSndChannel]             ; $459A
    cp $03                          ; $459C
    jr z,.write                     ; $459E
    ld c,$10                        ; $45A0
.write
    ld a,e                          ; $45A2
    ldh [c],a                       ; $45A3 NR10 (ch1) or NR43 (ch4)
    ret                             ; $45A4

; Snd_SeqTick (ch4 only): step the noise list. $FE = restart the drum, $FF = stop.
Snd_SeqTick:
    ld l,TRK_FLAGS                  ; $45A5
    call Snd_GetVar                 ; $45A7
    bit 4,a                         ; $45AA
    ret z                           ; $45AC
    ld l,TRK_SEQCOUNT               ; $45AD
    call Snd_GetVar                 ; $45AF
    dec [hl]                        ; $45B2
    ret nz                          ; $45B3
    call Snd_SeqNextStep            ; $45B4
    ld a,d                          ; $45B7
    cp $FE                          ; $45B8
    jp z,Snd_DrumInit               ; $45BA $FE: restart the drum
    cp $FF                          ; $45BD $FF: stop
    jr nz,.retrigger                ; $45BF
    ld l,TRK_FLAGS                  ; $45C1
    call Snd_GetVar                 ; $45C3
    res 4,[hl]                      ; $45C6
    ret                             ; $45C8
.retrigger
    ldh a,[hSndMuted]               ; $45C9
    or a                            ; $45CB
    ret nz                          ; $45CC
    inc a                           ; $45CD
    ldh [hSndRetrigger],a           ; $45CE
    ret                             ; $45D0

; Snd_DoCommand: a = command byte $A0-$B7, de = argument pointer.
Snd_DoCommand:
    sub $A0                         ; $45D1
    add a,a                         ; $45D3
    ld c,a                          ; $45D4
    ld b,$00                        ; $45D5
    ld hl,CommandTable              ; $45D7
    add hl,bc                       ; $45DA
    ld a,[hl+]                      ; $45DB
    ld h,[hl]                       ; $45DC
    ld l,a                          ; $45DD
    jp hl                           ; $45DE
Cmd_DefaultLength:
    ld a,[de]                       ; $45DF
    inc de                          ; $45E0
    call Snd_GetLength              ; $45E1
    ld l,TRK_DEFLEN                 ; $45E4
    jp Snd_SetVar                   ; $45E6

; Snd_GetLength: a = length code $80-$9F -> ticks from LengthTable.
Snd_GetLength:
    sub $80                         ; $45E9
    ld hl,LengthTable               ; $45EB
    ld c,a                          ; $45EE
    ld b,$00                        ; $45EF
    add hl,bc                       ; $45F1
    ld a,[hl]                       ; $45F2
    ret                             ; $45F3

; Cmd_End ($A0). SFX track: stop the SFX and give the channel back to the music.
; Music track: loop to TRK_START, or stop the channel if $A2 (no-loop) is set.
Cmd_End:
    ldh a,[hSndStructOfs]           ; $45F4
    cp $C0                          ; $45F6 SFX struct?
    jr nz,.music                    ; $45F8
    call Snd_NoteOff                ; $45FA SFX end: release the channel
    ldh a,[hSndFlags]               ; $45FD
    res 4,a                         ; $45FF
    ldh [hSndFlags],a               ; $4601
    xor a                           ; $4603
    ldh [hSndSfxPriority],a         ; $4604 SFX priority = 0
    ldh a,[hSndSfxChannel]          ; $4606
    or a                            ; $4608
    jr nz,.notCh1                   ; $4609
    ld a,$08                        ; $460B
    ldh [rNR14],a                   ; $460D ch1: NR14 = $08 first
    ld c,$12                        ; $460F
    jr .silence                     ; $4611
.notCh1
    ld c,$17                        ; $4613
    dec a                           ; $4615
    jr z,.silence                   ; $4616
    dec a                           ; $4618
    jr z,.release                   ; $4619
    ld c,$21                        ; $461B
.silence
    ld a,$08                        ; $461D
    ldh [c],a                       ; $461F NRx2 = 8
    inc c                           ; $4620
    inc c                           ; $4621
    ld a,$80                        ; $4622
    ldh [c],a                       ; $4624 NRx4 = trigger
.release
    ldh a,[hSndSfxChannel]          ; $4625
    call Snd_GetStructAddr          ; $4627 music struct of that channel
    ld c,l                          ; $462A
    ld a,$0E                        ; $462B
    add a,l                         ; $462D
    ld l,a                          ; $462E
    res 0,[hl]                      ; $462F not SFX-owned any more
    set 7,[hl]                      ; $4631 pause its effects until the next row
    ld a,c                          ; $4633 bug: meant to read TRK_PAN (no ld l,a), so a = TRK_FLAGS (>= $80) and
    add a,$13                       ; $4634
    ld a,[hl]                       ; $4636 the channel always gets centre pan
    jp Snd_SetPan                   ; $4637
.music
    ldh a,[hSndFlags]               ; $463A
    bit 7,a                         ; $463C no-loop mode?
    jr z,.loop                      ; $463E
    call Snd_NoteOff                ; $4640
    jp Snd_StopChannel              ; $4643
.loop
    ld l,TRK_START                  ; $4646
    call Snd_GetVarWord             ; $4648 de = TRK_START
    ld e,c                          ; $464B
    ld d,b                          ; $464C
    inc hl                          ; $464D TRK_PTR = TRK_START
    ld [hl],c                       ; $464E
    inc hl                          ; $464F
    ld [hl],b                       ; $4650
    ld a,[de]                       ; $4651
    cp $A0                          ; $4652 empty track: stop
    ret nz                          ; $4654
    jp Snd_StopChannel              ; $4655

; Snd_StopChannel: clear the channel bit in hSndFlags.
Snd_StopChannel:
    ldh a,[hSndChannel]             ; $4658
    ld b,$FE                        ; $465A
    or a                            ; $465C
    jr z,.clear                     ; $465D
    ld b,$FD                        ; $465F
    dec a                           ; $4661
    jr z,.clear                     ; $4662
    ld b,$FB                        ; $4664
    dec a                           ; $4666
    jr z,.clear                     ; $4667
    ld b,$F7                        ; $4669
.clear
    ldh a,[hSndFlags]               ; $466B
    and b                           ; $466D
    ldh [hSndFlags],a               ; $466E
    ret                             ; $4670

; Snd_IsChannelOn: nz if this music channel is still running.
Snd_IsChannelOn:
    ldh a,[hSndChannel]             ; $4671
    ld b,$01                        ; $4673
    or a                            ; $4675
    jr z,.test                      ; $4676
    ld b,$02                        ; $4678
    dec a                           ; $467A
    jr z,.test                      ; $467B
    ld b,$04                        ; $467D
    dec a                           ; $467F
    jr z,.test                      ; $4680
    ld b,$08                        ; $4682
.test
    ldh a,[hSndFlags]               ; $4684
    and b                           ; $4686
    ret                             ; $4687
Cmd_Volume:
    ld a,[de]                       ; $4688
    inc de                          ; $4689
    ld c,a                          ; $468A
    ldh a,[hSndChannel]             ; $468B
    cp $02                          ; $468D
    jr nz,.store                    ; $468F ch3: NR32 value from WaveVolTable
    ld hl,WaveVolTable              ; $4691
    ld b,$00                        ; $4694
    add hl,bc                       ; $4696
    ld c,[hl]                       ; $4697
.store
    ld a,c                          ; $4698
    ld l,TRK_VOLUME                 ; $4699
    jp Snd_SetVar                   ; $469B
Cmd_MasterVolume:
    ld a,[de]                       ; $469E
    inc de                          ; $469F
    ldh [hSndMasterVol],a           ; $46A0
    ldh [rNR50],a                   ; $46A2 NR50
    ret                             ; $46A4
Cmd_Slur:
    ld a,$01                        ; $46A5
    ldh [hSndSlur],a                ; $46A7
    ret                             ; $46A9
Cmd_LoopOn:
    ld hl,hSndFlags                 ; $46AA
    res 7,[hl]                      ; $46AD
    ret                             ; $46AF
Cmd_LoopOff:
    ld hl,hSndFlags                 ; $46B0
    set 7,[hl]                      ; $46B3
    ret                             ; $46B5
Cmd_Tempo:
    ld a,[de]                       ; $46B6
    inc de                          ; $46B7
    ld b,a                          ; $46B8
    ldh a,[hSndStructOfs]           ; $46B9
    cp $C0                          ; $46BB not from the SFX
    ret z                           ; $46BD
    ld a,b                          ; $46BE
    ldh [hSndTempo],a               ; $46BF tempo (and tick on the next frame)
    ldh [hSndTempoCount],a          ; $46C1
    ret                             ; $46C3
Cmd_Marker:
    ld a,[de]                       ; $46C4
    inc de                          ; $46C5
    ldh [hSndMarker],a              ; $46C6
    ret                             ; $46C8
Cmd_Duty:
    ld a,[de]                       ; $46C9
    inc de                          ; $46CA
    ld b,a                          ; $46CB
    ldh a,[hSndChannel]             ; $46CC
    cp $02                          ; $46CE ch1/ch2 only
    ret nc                          ; $46D0
    ld a,b                          ; $46D1
    swap a                          ; $46D2 arg * $40
    add a,a                         ; $46D4
    add a,a                         ; $46D5
    ld l,TRK_DUTY                   ; $46D6
    jp Snd_SetVar                   ; $46D8
Cmd_SeqTable:
    ld a,[de]                       ; $46DB
    ld c,a                          ; $46DC
    inc de                          ; $46DD
    ld a,[de]                       ; $46DE
    inc de                          ; $46DF
    ld b,a                          ; $46E0
    ld l,TRK_SEQTABLE               ; $46E1
    call Snd_SetVarWord             ; $46E3
    ld l,TRK_FLAGS                  ; $46E6
    call Snd_GetVarH                ; $46E8
    set 3,[hl]                      ; $46EB
    ret                             ; $46ED
Cmd_Envelope:
    ld a,[de]                       ; $46EE
    inc de                          ; $46EF
    ld c,a                          ; $46F0
    ld a,[de]                       ; $46F1
    inc de                          ; $46F2
    ld b,a                          ; $46F3
Snd_SetEnvelope:
    ld l,TRK_ENVBASE                ; $46F4
    call Snd_SetVarWord             ; $46F6
    ld l,TRK_FLAGS                  ; $46F9
    call Snd_GetVarH                ; $46FB
    set 2,[hl]                      ; $46FE
    ret                             ; $4700
Cmd_Wave:
    ld a,[de]                       ; $4701 first argument byte is not used
    inc de                          ; $4702
    call Snd_ReadPtrPtr             ; $4703
    ldh a,[hSndMuted]               ; $4706
    or a                            ; $4708 not while muted
    ret nz                          ; $4709
    ldh [rNR30],a                   ; $470A NR30 = 0
    ld c,$30                        ; $470C
    ld b,$10                        ; $470E
.copy
    ld a,[hl+]                      ; $4710
    ldh [c],a                       ; $4711 wave RAM
    inc c                           ; $4712
    dec b                           ; $4713
    jr nz,.copy                     ; $4714
    ld a,$80                        ; $4716
    ldh [rNR30],a                   ; $4718 NR30 = $80
    ldh [hSndRetrigger],a           ; $471A retrigger
    ret                             ; $471C
Snd_ReadPtrPtr:
    ld a,[de]                       ; $471D
    inc de                          ; $471E
    ld l,a                          ; $471F
    ld a,[de]                       ; $4720
    inc de                          ; $4721
    ld h,a                          ; $4722
    ld a,[hl+]                      ; $4723 hl = word at the pointer
    ld h,[hl]                       ; $4724
    ld l,a                          ; $4725
    ret                             ; $4726
Cmd_Pan:
    ld a,[de]                       ; $4727
    inc de                          ; $4728
    ld l,TRK_PAN                    ; $4729
    call Snd_SetVar                 ; $472B
    ld l,TRK_PAN                    ; $472E
    call Snd_GetVar                 ; $4730
    and $03                         ; $4733 1 = right, 2 = left, else both
Snd_SetPan:
    ld b,$01                        ; $4735
    ld c,$EE                        ; $4737
    dec a                           ; $4739
    jr z,.shift                     ; $473A
    ld b,$10                        ; $473C
    ld c,$EE                        ; $473E
    dec a                           ; $4740
    jr z,.shift                     ; $4741
    ld b,$11                        ; $4743
    ld c,$EE                        ; $4745
.shift
    ldh a,[hSndChannel]             ; $4747
    or a                            ; $4749
    jr z,.write                     ; $474A
.shiftLoop
    rlc b                           ; $474C shift to this channel
    rlc c                           ; $474E
    dec a                           ; $4750
    jr nz,.shiftLoop                ; $4751
.write
    ldh a,[hSndMuted]               ; $4753
    or a                            ; $4755
    ret nz                          ; $4756
    ldh a,[rNR51]                   ; $4757 NR51
    and c                           ; $4759
    or b                            ; $475A
    ldh [rNR51],a                   ; $475B
    ret                             ; $475D
Cmd_Call:
    ld a,[de]                       ; $475E
    inc de                          ; $475F
    ld l,TRK_CALLCOUNT              ; $4760
    call Snd_SetVar                 ; $4762 repeat count
    ld c,e                          ; $4765
    ld b,d                          ; $4766
    ld l,TRK_CALLRET                ; $4767
    call Snd_SetVarWord             ; $4769 TRK_CALLRET = address of the pointer
    ld l,e                          ; $476C
    ld h,d                          ; $476D
    ld e,[hl]                       ; $476E jump to the subroutine
    inc hl                          ; $476F
    ld d,[hl]                       ; $4770
    ret                             ; $4771
Cmd_Return:
    ld l,TRK_CALLCOUNT              ; $4772
    call Snd_GetVar                 ; $4774
    dec [hl]                        ; $4777 last pass?
    jr nz,.again                    ; $4778
    ld l,TRK_CALLRET                ; $477A
    call Snd_GetVarWordH            ; $477C
    inc bc                          ; $477F continue after the $AC pointer
    inc bc                          ; $4780
    jr .jump                        ; $4781
.again
    ld l,TRK_CALLRET                ; $4783
    call Snd_GetVarWordH            ; $4785
    ld l,c                          ; $4788
    ld h,b                          ; $4789
    ld c,[hl]                       ; $478A run the subroutine again
    inc hl                          ; $478B
    ld b,[hl]                       ; $478C
.jump
    ld e,c                          ; $478D
    ld d,b                          ; $478E
    ret                             ; $478F
Cmd_Jump:
    ld l,e                          ; $4790
    ld h,d                          ; $4791
    ld e,[hl]                       ; $4792 de = target
    inc hl                          ; $4793
    ld d,[hl]                       ; $4794
    ret                             ; $4795
Cmd_Detune:
    ld a,[de]                       ; $4796
    inc de                          ; $4797
    ld l,TRK_DETUNE                 ; $4798
    jp Snd_SetVar                   ; $479A
Cmd_Transpose:
    ld a,[de]                       ; $479D
    inc de                          ; $479E
    ld l,TRK_TRANSPOSE              ; $479F
    jp Snd_SetVar                   ; $47A1
Cmd_Gate:
    ld a,[de]                       ; $47A4
    and $07                         ; $47A5 0-7
    inc de                          ; $47A7
    ld l,TRK_GATE                   ; $47A8
    jp Snd_SetVar                   ; $47AA
Cmd_LoopStart:
    xor a                           ; $47AD
    ld l,TRK_LOOPCOUNT              ; $47AE
    call Snd_SetVar                 ; $47B0 pass = 0
    ld c,e                          ; $47B3
    ld b,d                          ; $47B4
    ld l,TRK_LOOPPTR                ; $47B5
    jp Snd_SetVarWord               ; $47B7 TRK_LOOPPTR = here
Cmd_LoopEnd:
    ld a,[de]                       ; $47BA
    inc de                          ; $47BB
    ld b,a                          ; $47BC
    ld l,TRK_LOOPCOUNT              ; $47BD
    call Snd_GetVar                 ; $47BF
    inc [hl]                        ; $47C2 pass + 1
    ld a,[hl]                       ; $47C3
    cp b                            ; $47C4
    ret nc                          ; $47C5 last pass: continue
    ld l,TRK_LOOPPTR                ; $47C6
    call Snd_GetVarWordH            ; $47C8
    ld e,c                          ; $47CB back to the loop start
    ld d,b                          ; $47CC
    ret                             ; $47CD
Cmd_Vibrato:
    ld a,[de]                       ; $47CE
    and $3F                         ; $47CF bits 0-5: depth
    ld l,TRK_VIBDEPTH               ; $47D1
    call Snd_SetVar                 ; $47D3
    ld a,[de]                       ; $47D6
    inc de                          ; $47D7
    swap a                          ; $47D8
    rra                             ; $47DA
    rra                             ; $47DB
    and $03                         ; $47DC bits 6-7: mode
    ld l,TRK_VIBMODE                ; $47DE
    call Snd_SetVar                 ; $47E0
    ld a,[de]                       ; $47E3
    inc de                          ; $47E4
    ld l,TRK_VIBDELAYR              ; $47E5
    call Snd_SetVar                 ; $47E7 delay
    ld a,[de]                       ; $47EA
    inc de                          ; $47EB
    ld l,TRK_VIBRATER               ; $47EC
    call Snd_SetVar                 ; $47EE rate
    ld a,[de]                       ; $47F1
    inc de                          ; $47F2
    ld l,TRK_VIBHALFR               ; $47F3
    call Snd_SetVar                 ; $47F5 half period
    xor a                           ; $47F8
    ld l,TRK_DETUNE                 ; $47F9
    jp Snd_SetVar                   ; $47FB detune = 0

; Track struct accessors: l = offset (TRK_*), result in a / bc.
Snd_GetVar:
    ld h,HIGH(wSndTracks)           ; $47FE
Snd_GetVarH:
    ldh a,[hSndStructOfs]           ; $4800
    add a,l                         ; $4802
    ld l,a                          ; $4803
    ld a,[hl]                       ; $4804
    ret                             ; $4805
Snd_GetVarWord:
    ld h,HIGH(wSndTracks)           ; $4806
Snd_GetVarWordH:
    ldh a,[hSndStructOfs]           ; $4808
    add a,l                         ; $480A
    ld l,a                          ; $480B
    ld a,[hl+]                      ; $480C
    ld c,a                          ; $480D
    ld b,[hl]                       ; $480E
    ret                             ; $480F

; Track struct accessors: l = offset, h is set to the struct page here.
Snd_SetVar:
    ld h,a                          ; $4810
    ldh a,[hSndStructOfs]           ; $4811
    add a,l                         ; $4813
    ld l,a                          ; $4814
    ld a,h                          ; $4815
    ld h,HIGH(wSndTracks)           ; $4816
    ld [hl],a                       ; $4818
    ret                             ; $4819
Snd_SetVarWord:
    ld h,HIGH(wSndTracks)           ; $481A
    ldh a,[hSndStructOfs]           ; $481C
    add a,l                         ; $481E
    ld l,a                          ; $481F
    ld a,c                          ; $4820
    ld [hl+],a                      ; $4821
    ld [hl],b                       ; $4822
    ret                             ; $4823

; Snd_StartSfx: hl -> pointer to the SFX header.
Snd_StartSfx:
    ldh a,[rIE]                     ; $4824 IE: mask the LCD STAT interrupt (bit 1)
    push af                         ; $4826
    res 1,a                         ; $4827
    ldh [rIE],a                     ; $4829
    ld a,[hl+]                      ; $482B
    ld h,[hl]                       ; $482C
    ld l,a                          ; $482D
    ld b,[hl]                       ; $482E
    inc hl                          ; $482F
    ldh a,[hSndSfxPriority]         ; $4830
    ld c,a                          ; $4832
    ld a,[hl]                       ; $4833
    cp c                            ; $4834 lower priority than the current SFX: ignore
    jr c,.done                      ; $4835
    ldh a,[hSndFlags]               ; $4837
    bit 4,a                         ; $4839 SFX already playing?
    jr z,.start                     ; $483B
    push bc                         ; $483D
    push hl                         ; $483E
    ldh a,[hSndChannel]             ; $483F
    push af                         ; $4841
    ldh a,[hSndStructOfs]           ; $4842
    push af                         ; $4844
    ldh a,[hSndSfxChannel]          ; $4845
    ldh [hSndChannel],a             ; $4847
    ld a,$C0                        ; $4849
    ldh [hSndStructOfs],a           ; $484B
    xor a                           ; $484D
    ldh [hSndMuted],a               ; $484E
    call Cmd_End                    ; $4850 end it first
    pop af                          ; $4853
    ldh [hSndStructOfs],a           ; $4854
    pop af                          ; $4856
    ldh [hSndChannel],a             ; $4857
    pop hl                          ; $4859
    pop bc                          ; $485A
.start
    ld a,[hl+]                      ; $485B
    ldh [hSndSfxPriority],a         ; $485C priority
    ld a,b                          ; $485E
    ldh [hSndSfxChannel],a          ; $485F target channel
    push hl                         ; $4861
    call Snd_GetStructAddr          ; $4862
    ld a,$0E                        ; $4865
    add a,l                         ; $4867
    ld l,a                          ; $4868
    set 0,[hl]                      ; $4869 mark the music track as SFX-owned
    pop de                          ; $486B
    ld a,$04                        ; $486C
    call Snd_InitTrack              ; $486E struct 4 = the SFX
    ld hl,hSndFlags                 ; $4871
    set 4,[hl]                      ; $4874 SFX on
.done
    pop af                          ; $4876
    ldh [rIE],a                     ; $4877 restore IE
    ret                             ; $4879

; Sound_Init: power the APU on, set all registers from InitRegs, clear the
; flags of all 5 structs, then fall into Sound_StopMusic.
Sound_Init::
    ld c,$26                        ; $487A
    xor a                           ; $487C
    ldh [c],a                       ; $487D APU off
    ld a,$8F                        ; $487E
    ldh [c],a                       ; $4880 APU on
    dec c                           ; $4881
    ld a,$FF                        ; $4882
    ldh [c],a                       ; $4884 NR51 = $FF
    dec c                           ; $4885
    ld a,$77                        ; $4886
    ldh [c],a                       ; $4888 NR50 = $77
    ld hl,InitRegs                  ; $4889
    ld c,$10                        ; $488C
.regLoop
    ld a,[hl+]                      ; $488E
    ldh [c],a                       ; $488F NR10-NR23 from InitRegs
    inc c                           ; $4890
    ld a,c                          ; $4891
    cp $24                          ; $4892
    jr c,.regLoop                   ; $4894
    xor a                           ; $4896
    ldh [hSndFlags],a               ; $4897
    ldh [hSndMarker],a              ; $4899
    ldh [hSndSfxChannel],a          ; $489B
    ldh [hSndSfxPriority],a         ; $489D
.flagLoop
    push af                         ; $489F
    call Snd_GetStructAddr          ; $48A0
    ld a,$0E                        ; $48A3
    add a,l                         ; $48A5
    ld l,a                          ; $48A6
    ld [hl],$00                     ; $48A7 flags = 0
    pop af                          ; $48A9
    inc a                           ; $48AA
    cp $05                          ; $48AB
    jr nz,.flagLoop                 ; $48AD

; Sound_StopMusic: start the silent song.
Sound_StopMusic::
    ld hl,SilentSong                ; $48AF

; Snd_StartMusic: hl -> 4 track pointers. Tempo 4, all 4 channels on.
Snd_StartMusic:
    ldh a,[rIE]                     ; $48B2 IE: mask the LCD STAT interrupt (bit 1)
    push af                         ; $48B4
    res 1,a                         ; $48B5
    ldh [rIE],a                     ; $48B7
    ldh a,[hSndFlags]               ; $48B9
    and $F0                         ; $48BB
    ldh [hSndFlags],a               ; $48BD channels off
    ld a,$04                        ; $48BF
    ldh [hSndTempoCount],a          ; $48C1
    ldh [hSndTempo],a               ; $48C3 tempo 4, tick at once
    xor a                           ; $48C5
.trackLoop
    ld e,[hl]                       ; $48C6
    inc hl                          ; $48C7
    ld d,[hl]                       ; $48C8
    inc hl                          ; $48C9
    push af                         ; $48CA
    push hl                         ; $48CB
    call Snd_InitTrack              ; $48CC
    pop hl                          ; $48CF
    pop af                          ; $48D0
    inc a                           ; $48D1
    cp $04                          ; $48D2
    jr c,.trackLoop                 ; $48D4
    ld a,$01                        ; $48D6
    ld [$00A8],a                    ; $48D8 writes to ROM ($0000-$1FFF = MBC RAM-enable); looks like a typo for RAM vars
    ld [$00A9],a                    ; $48DB
    ld a,$80                        ; $48DE
    ldh [rNR30],a                   ; $48E0
    call Snd_WaveOff                ; $48E2 NR32 = 0, NR30 = 0
    ldh a,[hSndFlags]               ; $48E5
    or $0F                          ; $48E7
    ldh [hSndFlags],a               ; $48E9 channels 1-4 on
    pop af                          ; $48EB
    ldh [rIE],a                     ; $48EC restore IE
    ret                             ; $48EE

; Snd_InitTrack: a = struct index, de = data. Clears the struct (keeps
; TRKF_SFXOWNED), TRK_START = TRK_PTR = de, default length 1, volume $C.
Snd_InitTrack:
    call Snd_GetStructAddr          ; $48EF
    ld a,$0E                        ; $48F2
    add a,l                         ; $48F4
    ld c,a                          ; $48F5
    ld b,h                          ; $48F6
    ld a,[bc]                       ; $48F7
    and $01                         ; $48F8
    push af                         ; $48FA keep TRKF_SFXOWNED
    push bc                         ; $48FB
    push hl                         ; $48FC
    xor a                           ; $48FD
    ld b,$30                        ; $48FE
.clear
    ld [hl+],a                      ; $4900
    dec b                           ; $4901
    jr nz,.clear                    ; $4902
    pop hl                          ; $4904
    pop bc                          ; $4905
    pop af                          ; $4906
    ld [bc],a                       ; $4907
    ld a,l                          ; $4908
    ld [hl],e                       ; $4909
    inc hl                          ; $490A TRK_START
    ld [hl],d                       ; $490B
    inc hl                          ; $490C
    ld [hl],e                       ; $490D
    inc hl                          ; $490E TRK_PTR
    ld [hl],d                       ; $490F
    add a,$0F                       ; $4910
    ld l,a                          ; $4912
    ld a,$01                        ; $4913
    ld [hl+],a                      ; $4915 TRK_DEFLEN = 1, TRK_LENGTH = 1
    ld [hl+],a                      ; $4916
    ld [hl],$0C                     ; $4917 TRK_VOLUME = $C
    ret                             ; $4919

; Snd_GetStructAddr: hl = struct a (a * $30).
Snd_GetStructAddr:
    push af                         ; $491A
    ld h,a                          ; $491B
    inc h                           ; $491C
    ld a,$00                        ; $491D
.mulLoop
    dec h                           ; $491F
    jr z,.done                      ; $4920
    add a,$30                       ; $4922
    jr .mulLoop                     ; $4924
.done
    ld l,a                          ; $4926
    ld h,HIGH(wSndTracks)           ; $4927
    pop af                          ; $4929
    ret                             ; $492A

